/**
 * WebUI Page Host 根据 manifest 渲染导航与面板，并管理挂载和卸载；不依赖具体页的名称。扩展加载、mount 或面板解析失败仅将对应面板替换为错误卡，不影响其他页与框架。
 */

import { WEBUI_PROTOCOL_VERSION } from '../../shared/webui-protocol.ts';
import type { WebUiManifest, WebUiPageManifest, WebUiStorageRef, WebUiPanelManifest } from '../../shared/webui-protocol.ts';
import type { WebUiMemo, WebUiPanelContext, Disposable } from '../../shared/client-panel.ts';
import { get, post } from '../core/api.ts';
import { Lifecycle } from '../core/lifecycle.ts';
import type { Router } from '../core/router.ts';
import type { SocketLike } from '../core/stream.ts';
import { createWebUi } from '../ui/index.ts';
import { pageTabs, type PageTabs } from '../ui/page-tabs.ts';
import { pageBadges } from '../ui/page-badges.ts';
import { createConfigView, type ConfigValue } from '../features/config/view.ts';
import type { ToolSchemaDoc } from '../features/live/protocol.ts';
import { createTemplateView } from '../features/prompts/template-view.ts';
import { createPromptsView } from '../features/prompts/view.ts';
import { createStorageView } from '../features/storage/view.ts';
import { S as TOOLS } from './tools/strings.ts';
import { createToolsView } from './tools/view.ts';
import { resolveWebUiLinkHref } from '../theme/handoff.ts';
import { createPanelContext, namespacedMemo } from './context.ts';
import { WebUiPageLoader } from './loader.ts';
import { S } from './strings.ts';
import { S as WORLD } from '../features/worlds/strings.ts';
import { takeReturn } from '../core/world-nav.ts';
import { icon } from '../ui/icons.ts';

/** WebUI 页路由的首段，与框架页路由分开。 */
export const PROVIDER_ROUTE = 'provider';
/** 框架页签由 promptDocs、config 与 storage 声明生成；~ 前缀不在合法 panel id 字符集中。 */
const PROVIDER_PROMPTS_ROUTE = '~prompts';
const PROVIDER_CONFIG_ROUTE = '~config';
const PROVIDER_STORAGE_ROUTE = '~storage';
/** 工具表不来自页面声明:装配好的那一份整个属于 Persona,所以只挂在 Persona 页上。 */
const PROVIDER_TOOLS_ROUTE = '~tools';

function asArray<T>(v: readonly T[] | undefined): readonly T[] {
  return Array.isArray(v) ? v : [];
}

/** 页签只给独立面板；带 slot 的由宿主面板挂。 */
function tabbed(page: WebUiPageManifest): readonly WebUiPanelManifest[] {
  return asArray(page.panels).filter((p) => p.slot === undefined);
}

export interface WebUiPageHostDeps {
  doc: Document;
  /** 页面内容渲染到这里。host 自己清空/重建它。 */
  root: HTMLElement;
  /** 浮层宿主，页面级容器；绝不能是 `root`。 */
  overlayHost: HTMLElement;
  loader: WebUiPageLoader;
  router: Router;
  fetchManifest(): Promise<WebUiManifest>;
  memo: WebUiMemo;
  createSocket(url: string): SocketLike;
  wsUrl(path: string): string;
  onError(err: unknown): void;
  /**
   * 面板页签指向的路由。缺省是 `#/provider/<id>/<panel>`;嵌在别的框架页里的宿主
   * 给自己那一页的前缀,页签切换才不会跳出那一页。
   */
  route?(pageId: string, panelId: string): readonly string[];
}

interface MountedPanel {
  pageId: string;
  panelId: string;
  lifecycle: Lifecycle;
}

/** 页头与面板使用独立容器，刷新页头不重挂面板。 */
interface Panes {
  chrome: HTMLElement;
  slot: HTMLElement;
}

export class WebUiPageHost {
  private readonly deps: WebUiPageHostDeps;
  private snapshot: WebUiManifest | null = null;
  private mounted: MountedPanel | null = null;
  /** The World page this visit came to from the World list; its header shows a way back. */
  private backFor: string | null = null;
  /** Per World page, the values its restart-only settings had when the World last started; kept while the window is open. */
  private readonly restartApplied = new Map<string, Map<string, ConfigValue>>();
  private panes: Panes | null = null;
  /** 页头里的页签。同一页内切换页签且页头内容没变时保留它，下面那根线才能滑过去。 */
  private tabs: { pageId: string; key: string; bar: PageTabs } | null = null;
  /**
   * 挂载代号。异步 mount 期间用户可能已经走了；回来时对不上号就整个丢弃，
   * 免得把一个已经不该存在的面板贴进 DOM。
   */
  private generation = 0;
  private chromeStop: AbortController | null = null;
  private readonly navListeners = new Set<() => void>();

  constructor(deps: WebUiPageHostDeps) {
    this.deps = deps;
  }

  get pages(): WebUiPageManifest[] {
    return this.snapshot?.providers ?? [];
  }

  /** 取一次 manifest。失败时保留上一份（一次网络抖动不该让导航整个消失）。 */
  async load(): Promise<void> {
    try {
      const next = await this.deps.fetchManifest();
      // 拒绝不支持的协议版本。
      if (next && next.protocolVersion !== WEBUI_PROTOCOL_VERSION) {
        throw new Error(S.protocolMismatch(String(next.protocolVersion), String(WEBUI_PROTOCOL_VERSION)));
      }
      this.snapshot = next;
    } catch (err) {
      this.deps.onError(err);
      if (!this.snapshot) {
        this.snapshot = {
          protocolVersion: WEBUI_PROTOCOL_VERSION,
          providers: [],
          framework: { capabilities: {} },
        };
      }
    }
    this.emitNav();
  }

  /** Mount one of a page's panels inside the connection editor; `adapt` stages the panel's configuration edits. */
  async mountConnection(pageId: string, panelId: string, root: HTMLElement, scope: Readonly<Record<string, string>>,
    adapt: (context: WebUiPanelContext) => WebUiPanelContext): Promise<Disposable> {
    const lifecycle = new Lifecycle(this.deps.onError);
    const page = this.find(pageId);
    const panel = asArray(page?.panels).find(candidate => candidate.id === panelId);
    try {
      if (!panel) throw new Error(S.noSuchPanel(page?.label ?? pageId, panelId));
      if (panel.builtin !== undefined) throw new Error(S.noBuiltinPanel(panel.builtin));
      const impl = await this.deps.loader.resolvePanel(pageId, panel.id, page?.client);
      if (!lifecycle.disposed) {
        const result = await impl.mount(adapt(this.panelContext(pageId, panel.id, root, lifecycle, this.generation, scope)));
        if (result) lifecycle.own(result);
      }
    } catch (error) { root.textContent = String(error); }
    return lifecycle;
  }

  /** 重取 manifest 并刷新导航与当前页头，**不重挂面板**。 */
  async refresh(): Promise<void> {
    await this.load();
    const cur = this.mounted;
    if (cur) this.renderChrome(cur.pageId, cur.panelId);
  }

  onNavChange(cb: () => void): Disposable {
    this.navListeners.add(cb);
    return { dispose: () => this.navListeners.delete(cb) };
  }

  private emitNav(): void {
    for (const cb of [...this.navListeners]) {
      try {
        cb();
      } catch (err) {
        this.deps.onError(err);
      }
    }
  }

  find(pageId: string): WebUiPageManifest | undefined {
    return this.pages.find((p) => p.id === pageId);
  }

  private routeOf(pageId: string, panelId: string): readonly string[] {
    return this.deps.route ? this.deps.route(pageId, panelId) : [PROVIDER_ROUTE, pageId, panelId];
  }

  /** 卸载当前面板：abort → dispose → 清空 root。顺序见 client-panel.ts 的说明。 */
  unmount(): void {
    const cur = this.mounted;
    this.backFor = null;
    this.mounted = null;
    this.panes = null;
    this.chromeStop?.abort();
    this.chromeStop = null;
    this.tabs = null;
    this.generation++;
    if (cur) cur.lifecycle.dispose();
    this.deps.root.replaceChildren();
  }

  /** 同一页内换页签：只卸面板、清面板槽，页头留着，页签的选中滑块才能滑过去。 */
  private unmountPanel(): void {
    const cur = this.mounted;
    this.mounted = null;
    this.generation++;
    if (cur) cur.lifecycle.dispose();
    this.panes?.slot.replaceChildren();
  }

  /** 建（或复用）页头与面板槽两个容器。 */
  private ensurePanes(): Panes {
    if (this.panes) return this.panes;
    const doc = this.deps.doc;
    const chrome = doc.createElement('div');
    chrome.className = 'providerchrome';
    const slot = doc.createElement('div');
    slot.className = 'panelslot';
    this.deps.root.replaceChildren(chrome, slot);
    this.panes = { chrome, slot };
    return this.panes;
  }

  /**
   * 显示指定页的面板，省略 panelId 时选择第一个面板。每次调用先卸载上一面板，以重建完整生命周期。
   * 页头渲染、面板解析及 mount 均处于异常隔离范围，失败时显示该面板的错误卡，不使 show() 的错误扩散为路由空白。
   */
  async show(pageId: string, panelId?: string): Promise<void> {
    try {
      await this.showInner(pageId, panelId);
    } catch (err) {
      this.deps.onError(err);
      try {
        this.renderError(S.pageFailed(pageId), err instanceof Error ? err.message : String(err));
      } catch { /* 连错误卡都画不出来:那是 ui 层的事,不再往上抛 */ }
    }
  }

  private async showInner(pageId: string, panelId?: string): Promise<void> {
    if (this.tabs?.pageId === pageId) this.unmountPanel();
    else this.unmount();
    const gen = this.generation;

    const page = this.find(pageId);
    if (!page) {
      this.renderError(S.noPage(pageId), S.noPageHint);
      return;
    }
    const panels = tabbed(page);
    const prompts = asArray(page.prompts);
    const configGroups = this.configGroupsOf(page);
    const storage = this.storageOf(page);
    const tools = this.toolsTabOf(page);
    // 没指定页签时回到上次停留的那个(仍存在的话)；每次落到某个页签都记下来。
    const tabIds = this.tabsOf(page).map((t) => t.value);
    const memoKey = `tab:${pageId}`;
    const last = this.deps.memo.get<string>(memoKey, '');
    const wanted = panelId ?? (tabIds.includes(last) ? last : tabIds[0]);
    if (wanted && tabIds.includes(wanted)) this.deps.memo.set(memoKey, wanted);
    if (wanted === PROVIDER_CONFIG_ROUTE && configGroups.length) {
      this.renderChrome(pageId, PROVIDER_CONFIG_ROUTE);
      await this.showConfig(pageId, configGroups, gen);
      return;
    }
    if (wanted === PROVIDER_PROMPTS_ROUTE && prompts.length) {
      this.renderChrome(pageId, PROVIDER_PROMPTS_ROUTE);
      await this.showPrompts(pageId, prompts.map((doc) => doc.key), gen);
      return;
    }
    if (wanted === PROVIDER_STORAGE_ROUTE && storage.length) {
      this.renderChrome(pageId, PROVIDER_STORAGE_ROUTE);
      await this.showStorage(pageId, storage, gen);
      return;
    }
    if (wanted === PROVIDER_TOOLS_ROUTE && tools) {
      this.renderChrome(pageId, PROVIDER_TOOLS_ROUTE);
      await this.showTools(pageId, gen);
      return;
    }
    const panel = wanted ? panels.find((p) => p.id === wanted) : undefined;
    if (!panel) {
      this.renderChrome(pageId, wanted);
      if (tabIds.length === 0) {
        this.appendNote(S.noPanels(page.label));
      } else {
        this.renderError(S.noSuchPanel(page.label, wanted ?? ''), S.provides(tabIds.join(' / ')));
      }
      return;
    }

    this.renderChrome(pageId, panel.id);
    const { slot } = this.ensurePanes();

    const lifecycle = new Lifecycle(this.deps.onError);
    this.mounted = { pageId, panelId: panel.id, lifecycle };

    try {
      if (panel.builtin !== undefined) throw new Error(S.noBuiltinPanel(panel.builtin));
      const impl = await this.deps.loader.resolvePanel(pageId, panel.id, page.client);
      if (gen !== this.generation) return; // 等 import 的工夫用户已经走了

      const out = await impl.mount(
        this.panelContext(pageId, panel.id, slot, lifecycle, gen, {}),
      );
      if (gen !== this.generation) {
        // mount 返回时已卸载，立即释放其 Disposable。
        if (out && typeof out.dispose === 'function') out.dispose();
        return;
      }
      if (out && typeof out.dispose === 'function') lifecycle.own(out);
    } catch (err) {
      if (gen !== this.generation) return;
      this.deps.onError(err);
      lifecycle.dispose();
      slot.replaceChildren();
      this.renderErrorInto(
        slot,
        S.panelFailed(panel.title),
        err instanceof Error ? err.message : String(err),
      );
    }
  }

  /** 面板上下文。插槽里的面板与页签面板走同一条路，区别只在 root、生命周期与 scope。 */
  private panelContext(
    pageId: string,
    panelId: string,
    root: HTMLElement,
    lifecycle: Lifecycle,
    gen: number,
    scope: Readonly<Record<string, string>>,
  ) {
    return createPanelContext({
      pageId,
      panelId,
      root,
      lifecycle,
      scope,
      mountSlot: (name, host, childScope) =>
        this.mountSlot(pageId, gen, lifecycle, name, host, childScope),
      overlayHost: this.deps.overlayHost,
      refresh: () => this.refresh(),
      addLeaveGuard: (fn) => this.deps.router.addLeaveGuard(fn),
      memo: namespacedMemo(this.deps.memo, pageId, panelId),
      createSocket: this.deps.createSocket,
      wsUrl: this.deps.wsUrl,
      onError: this.deps.onError,
      doc: this.deps.doc,
    });
  }

  /**
   * 把声明到该插槽的面板按声明顺序挂进 host。整组共用一个生命周期，返回的句柄结束它们；
   * 单块面板挂不上只把该块换成错误卡。
   */
  private async mountSlot(
    pageId: string,
    gen: number,
    parent: Lifecycle,
    slot: string,
    host: HTMLElement,
    scope: Readonly<Record<string, string>>,
  ): Promise<Disposable> {
    const lifecycle = parent.own(new Lifecycle(this.deps.onError));
    const page = this.find(pageId);
    for (const decl of asArray(page?.panels).filter((p) => p.slot === slot)) {
      const box = this.deps.doc.createElement('div');
      host.appendChild(box);
      try {
        if (decl.builtin !== undefined) throw new Error(S.noBuiltinPanel(decl.builtin));
        const impl = await this.deps.loader.resolvePanel(pageId, decl.id, page?.client);
        if (gen !== this.generation || lifecycle.disposed) break;
        const out = await impl.mount(
          this.panelContext(pageId, decl.id, box, lifecycle, gen, scope),
        );
        if (out && typeof out.dispose === 'function') {
          if (gen !== this.generation || lifecycle.disposed) out.dispose();
          else lifecycle.own(out);
        }
      } catch (err) {
        this.deps.onError(err);
        box.replaceChildren();
        this.renderErrorInto(
          box,
          S.panelFailed(decl.title),
          err instanceof Error ? err.message : String(err),
        );
      }
    }
    return lifecycle;
  }

  /** 仅返回当前页认领且部署支持 config 能力的配置组。 */
  private configGroupsOf(page: WebUiPageManifest): readonly string[] {
    if (this.snapshot?.framework?.capabilities?.config === false) return [];
    return asArray(page.configGroups);
  }

  /** 仅返回当前页声明且部署支持 storage 能力的存储项。 */
  private storageOf(page: WebUiPageManifest): readonly WebUiStorageRef[] {
    if (this.snapshot?.framework?.capabilities?.storage === false) return [];
    return asArray(page.storageParts);
  }

  /** 这一页的页签,依次是面板、配置、提示词模板、数据清理、工具表(有的才列)。 */
  private tabsOf(page: WebUiPageManifest): Array<{ value: string; label: string }> {
    const prompts = asArray(page.prompts);
    return [
      ...tabbed(page).map((p) => ({ value: p.id, label: p.title || p.id })),
      ...(this.configGroupsOf(page).length ? [{ value: PROVIDER_CONFIG_ROUTE, label: S.configTab }] : []),
      ...(prompts.length ? [{ value: PROVIDER_PROMPTS_ROUTE, label: prompts.length === 1 ? prompts[0]!.title : S.promptsTab }] : []),
      ...(this.storageOf(page).length ? [{ value: PROVIDER_STORAGE_ROUTE, label: S.storageTab }] : []),
      ...(this.toolsTabOf(page) ? [{ value: PROVIDER_TOOLS_ROUTE, label: S.toolsTab }] : []),
    ];
  }

  /** Persona 页才有工具表页签,且要部署挂着 /api/tool-schemas。 */
  private toolsTabOf(page: WebUiPageManifest): boolean {
    if (page.kind !== 'persona' || page.availability !== 'active') return false;
    return this.snapshot?.framework?.capabilities?.toolSchemas !== false;
  }

  /** 工具表是整份装配结果,不按页筛:模型看见的那一张表就是这一张。 */
  private async showTools(pageId: string, gen: number): Promise<void> {
    const { slot } = this.ensurePanes();
    const lifecycle = new Lifecycle(this.deps.onError);
    this.mounted = { pageId, panelId: PROVIDER_TOOLS_ROUTE, lifecycle };
    const ui = createWebUi({
      memo: namespacedMemo(this.deps.memo, pageId, PROVIDER_TOOLS_ROUTE),
      overlayHost: this.deps.overlayHost,
      signal: lifecycle.signal,
      doc: this.deps.doc,
    });
    const view = createToolsView(ui);
    slot.appendChild(view.el);
    try {
      const out = await get<{ tools?: ToolSchemaDoc[] }>('/api/tool-schemas', { signal: lifecycle.signal });
      view.render(out?.tools ?? []);
    } catch (err) {
      if ((err as { name?: string } | null)?.name !== 'AbortError') {
        this.deps.onError(err);
        view.render([]);
        view.note(TOOLS.loadFailed(err instanceof Error ? err.message : String(err)));
      }
    }
    if (gen !== this.generation) lifecycle.dispose();
  }

  /** 这一页声明的存储项走同一张 /api/storage 清单;这里按归属与 key 挑出自己的。 */
  private async showStorage(pageId: string, refs: readonly WebUiStorageRef[], gen: number): Promise<void> {
    const { slot } = this.ensurePanes();
    const lifecycle = new Lifecycle(this.deps.onError);
    this.mounted = { pageId, panelId: PROVIDER_STORAGE_ROUTE, lifecycle };
    const ui = createWebUi({
      memo: namespacedMemo(this.deps.memo, pageId, PROVIDER_STORAGE_ROUTE),
      overlayHost: this.deps.overlayHost,
      signal: lifecycle.signal,
      doc: this.deps.doc,
    });
    const view = createStorageView({
      ui,
      signal: lifecycle.signal,
      filter: (part) => refs.some((r) => r.owner === part.owner && r.key === part.key),
    });
    slot.appendChild(view.el);
    await view.load();
    if (gen !== this.generation) lifecycle.dispose();
  }

  /** manifest 提供组 id，schema 与当前值取自 /api/config；页内省略重复 owner 标签。 */
  private async showConfig(pageId: string, groupIds: readonly string[], gen: number): Promise<void> {
    const { slot } = this.ensurePanes();
    const lifecycle = new Lifecycle(this.deps.onError);
    this.mounted = { pageId, panelId: PROVIDER_CONFIG_ROUTE, lifecycle };
    const ui = createWebUi({
      memo: namespacedMemo(this.deps.memo, pageId, PROVIDER_CONFIG_ROUTE),
      overlayHost: this.deps.overlayHost,
      signal: lifecycle.signal,
      doc: this.deps.doc,
    });
    const wanted = new Set(groupIds);
    const page = this.find(pageId);
    const worldId = page?.kind === 'world' ? pageId.slice('world:'.length) : undefined;
    const view = createConfigView({
      ui,
      lifecycle,
      signal: lifecycle.signal,
      filter: (group) => wanted.has(group.id),
      showOwner: false,
      emptyText: S.configEmpty,
      ...(worldId ? { restart: {
        label: WORLD.restartWorld,
        applied: this.restartApplied.get(pageId) ?? this.restartApplied.set(pageId, new Map()).get(pageId)!,
        run: async () => {
          if (!await ui.confirm({ title: WORLD.restartTitle(page?.label || worldId), body: WORLD.restartBody })) return false;
          await post('/api/worlds/restart', { id: worldId }, { signal: lifecycle.signal });
          return true;
        },
      } } : {}),
    });
    slot.appendChild(view.el);
    await view.load();
    if (gen !== this.generation) lifecycle.dispose();
  }

  /** 这一页声明的提示词模板仍由框架通用编辑器承载，扩展无需重复文件读写 UI。 */
  private async showPrompts(pageId: string, keys: readonly string[], gen: number): Promise<void> {
    const { slot } = this.ensurePanes();
    const lifecycle = new Lifecycle(this.deps.onError);
    this.mounted = { pageId, panelId: PROVIDER_PROMPTS_ROUTE, lifecycle };
    const ui = createWebUi({
      memo: namespacedMemo(this.deps.memo, pageId, PROVIDER_PROMPTS_ROUTE),
      overlayHost: this.deps.overlayHost,
      signal: lifecycle.signal,
      doc: this.deps.doc,
    });
    // World 的环境提示词用「系统提示词」页的编辑器
    const page = this.find(pageId);
    if (page?.kind === 'world') {
      const configured = this.configGroupsOf(page).length > 0;
      const view = createTemplateView({
        ui,
        lifecycle,
        signal: lifecycle.signal,
        addLeaveGuard: (fn) => this.deps.router.addLeaveGuard(fn),
        onError: this.deps.onError,
        keys,
        ...(configured ? { openConfig: () => this.deps.router.navigate(this.routeOf(pageId, PROVIDER_CONFIG_ROUTE)) } : {}),
      });
      slot.appendChild(view.el);
      await view.load();
      if (gen !== this.generation) lifecycle.dispose();
      return;
    }
    // 已在系统提示词里的模板与「系统提示词」页编辑的是同一份文件：这里照常列出，卡片标题旁标出同步。
    let inPrefix = new Set<string>();
    try {
      const out = await get<{ segments?: Array<{ sourceKey?: string }> }>('/api/prompts/prefix', { signal: lifecycle.signal });
      inPrefix = new Set((out?.segments ?? []).flatMap((seg) => (seg.sourceKey ? [seg.sourceKey] : [])));
    } catch (err) {
      if ((err as { name?: string } | null)?.name === 'AbortError') return;
      this.deps.onError(err); // 取不到前缀就不标同步
    }
    if (gen !== this.generation) { lifecycle.dispose(); return; }
    const view = createPromptsView({
      ui,
      lifecycle,
      signal: lifecycle.signal,
      addLeaveGuard: (fn) => this.deps.router.addLeaveGuard(fn),
      onError: this.deps.onError,
      keys,
      shared: inPrefix,
    });
    slot.appendChild(view.el);
    await view.load();
    if (gen !== this.generation) lifecycle.dispose();
  }

  // -------------------------------------------------------------------------
  // 页头与错误卡。都只吃 manifest 的通用字段。
  // -------------------------------------------------------------------------

  private ui(): ReturnType<typeof createWebUi> {
    // 页头是 host 自己的 DOM，生命周期跟 host 走，不绑任何面板。
    return createWebUi({
      memo: this.deps.memo,
      overlayHost: this.deps.overlayHost,
      signal: new AbortController().signal,
      doc: this.deps.doc,
    });
  }

  private renderChrome(pageId: string, activePanel?: string): void {
    const page = this.find(pageId);
    const { chrome } = this.ensurePanes();
    if (!page) {
      chrome.replaceChildren();
      this.chromeStop?.abort();
      this.chromeStop = null;
      this.tabs = null;
      return;
    }

    const items = this.tabsOf(page);
    // 页头里画的字段与页签都没变时才复用整个页头。
    // The visit that came from the World list keeps its way back while it stays on this page.
    if (this.backFor !== pageId) this.backFor = page.kind === 'world' && takeReturn(this.deps.doc.defaultView!, pageId) ? pageId : null;
    const back = this.backFor === pageId;
    const key = JSON.stringify([items, page.label, page.kind, page.availability, page.badges, page.agentVisible, page.prefixDrifted, page.reason, page.links, page.undeclared, back]);
    if (this.tabs && this.tabs.pageId === pageId && this.tabs.key === key) {
      this.tabs.bar.setValue(activePanel ?? '');
      return;
    }
    chrome.replaceChildren();
    this.chromeStop?.abort();
    this.chromeStop = new AbortController();
    this.tabs = null;
    const ui = this.ui();
    const head = ui.h('header', 'featureintro providerintro');
    head.classList.toggle('is-world', page.kind === 'world');
    const row = ui.h('div', 'pagetitle-row');
    // 人格与记忆页以用途作标题，实现名作小注；其余页仍用声明的名字。
    const purpose = page.kind === 'persona' ? S.personaTitle : page.kind === 'memory' ? S.memoryTitle : null;
    const title = ui.h('h1', 'pagetitle', purpose ?? page.label);
    if (purpose) title.appendChild(ui.h('span', 'pagetitle-name', page.label));
    // A World page opened from the World list leads back to it.
    if (back) {
      const button = ui.h('button', 'pagetitle-back') as HTMLButtonElement; button.type = 'button';
      button.title = S.backToWorlds; button.setAttribute('aria-label', S.backToWorlds); button.append(icon(this.deps.doc, 'arrow-left'));
      button.addEventListener('click', () => { this.backFor = null; this.deps.router.navigate(['world']); }, { signal: this.chromeStop.signal });
      row.appendChild(button);
    }
    row.appendChild(title);

    const badges = ui.h('div', 'pagetitle-badges');
    for (const badge of asArray(page.badges)) {
      badges.appendChild(ui.pill(`${badge.label} ${badge.value}`, badge.tone));
    }
    if (page.availability !== 'active') {
      badges.appendChild(ui.pill(page.availability === 'missing' ? S.notInstalled : S.notActivated, 'off'));
    }
    if (page.agentVisible === false) badges.appendChild(ui.pill(S.hidden, 'off'));
    if (badges.children.length && page.kind !== 'world') row.appendChild(badges);

    const actions = ui.h('div', 'pagetitle-actions');
    const textButton = (label: string, onClick: () => void): HTMLButtonElement => {
      const button = ui.h('button', 'pagetitle-link', label);
      button.type = 'button';
      button.addEventListener('click', onClick);
      return button;
    };
    if (page.prefixDrifted) actions.appendChild(textButton(S.reloadPrefix, () => { void this.reloadPrefix(ui); }));
    for (const link of asArray(page.links)) {
      actions.appendChild(textButton(link.label || S.open, () => {
        this.deps.doc.defaultView?.open(resolveWebUiLinkHref(this.deps.doc, link), '_blank', 'noopener');
      }));
    }
    if (actions.children.length) row.appendChild(actions);
    head.appendChild(row);
    if (page.kind === 'world' && badges.children.length) {
      head.append(pageBadges(this.deps.doc, this.deps.overlayHost, this.chromeStop.signal, Array.from(badges.children) as HTMLElement[]));
    }
    if (page.kind === 'memory') head.appendChild(ui.h('p', 'pagedesc', S.memoryDesc));
    chrome.append(head);

    if (items.length > 1) {
      const bar = pageTabs(this.deps.doc, this.chromeStop.signal, items, {
        value: activePanel ?? '',
        onSelect: (panelId) => this.deps.router.navigate(this.routeOf(page.id, panelId)),
      });
      bar.el.classList.add('providertabs');
      chrome.appendChild(bar.el);
      this.tabs = { pageId, key, bar };
    }
    if (page.reason) chrome.appendChild(ui.msgline(page.reason, true));
    const undeclared = [
      page.undeclared?.tools.length ? S.undeclaredTools(page.undeclared.tools.join(', ')) : '',
      page.undeclared?.events.length ? S.undeclaredEvents(page.undeclared.events.join(', ')) : '',
    ].filter(Boolean);
    if (undeclared.length) chrome.appendChild(ui.msgline(undeclared.join(' · ')));
  }

  /** 重载前缀后重新读取 manifest 中的漂移状态。 */
  private async reloadPrefix(ui: ReturnType<typeof createWebUi>): Promise<void> {
    const ok = await ui.confirm({
      title: S.reloadTitle,
      body: S.reloadBody,
    });
    if (!ok) return;
    try {
      const out = await post<{ result?: string }>('/api/session/reload-prefix');
      ui.toast(out?.result || S.prefixReloaded, 'ok');
      await this.refresh();
    } catch (err) {
      ui.toast(err instanceof Error ? err.message : String(err), 'bad');
    }
  }

  private appendNote(text: string): void {
    this.ensurePanes().slot.appendChild(this.ui().placeholder(text));
  }

  private renderError(title: string, detail: string): void {
    this.renderErrorInto(this.ensurePanes().slot, title, detail);
  }

  private renderErrorInto(target: HTMLElement, title: string, detail: string): void {
    const ui = this.ui();
    const card = ui.sheet({ title });
    card.body.appendChild(ui.msgline(detail, true));
    target.appendChild(card.el);
  }
}
